# Animation v2 · SE (chương mới) Shared element và chuyển màn hình
# Nguồn: SharedTransitionScope.kt @296313a4 (SharedTransitionLayout = SharedTransitionScope + Box; LookaheadScope; overlay; khớp key;
# isTransitionActive; isMatchFound; sharedElement vs sharedBounds; DefaultSpring StiffnessMediumLow); tài liệu shared-elements (+ customize,
# navigation); Android Animations by Tutorials Ch.6 (transitionName, addSharedElement, sharedElementEnterTransition, ChangeBounds).

def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)

    m = lambda k, vi, en=None: a('m.shared.' + k, vi, en)
    m('title', 'Shared element: khớp key, đo trước, bay trong overlay', 'Shared element: key match, lookahead, flight in the overlay')
    m('overview', 'Một ảnh nhỏ trong danh sách (64×64 ở góc) chuyển sang ảnh lớn ở màn chi tiết (360×240), trong `SharedTransitionLayout` + `AnimatedContent`. Ba cách viết: hai ảnh cùng key; hai ảnh khác key; và `clip(RoundedCornerShape)` đặt TRƯỚC `sharedElement`. Theo dõi khi nào khớp, ảnh được vẽ ở đâu, và khung bay ra sao.', 'A small list image (64×64 in the corner) becomes a large detail image (360×240), inside `SharedTransitionLayout` + `AnimatedContent`. Three versions: both images with the same key; different keys; and `clip(RoundedCornerShape)` placed BEFORE `sharedElement`. Watch when the match happens, where the image is drawn, and how its bounds fly.')
    m('wrapup', 'Shared element không phải phép màu: hai composable khai báo cùng một key trong cùng một SharedTransitionScope; khi nội dung mới được compose, scope tìm thấy cặp khớp, dùng lookahead để biết khung đích, rồi animate khung từ chỗ cũ tới chỗ mới. Trong lúc bay, phần tử được vẽ trong overlay của scope để không bị mờ hay cắt theo cha; vì vậy clip và fade muốn áp lên nó phải đặt SAU modifier shared.', 'A shared element is not magic: two composables declare the same key in the same SharedTransitionScope; when the new content is composed, the scope finds the matching pair, uses lookahead to learn the target bounds, then animates the bounds from the old place to the new one. During the flight, the element is drawn in the scope\'s overlay so it is not faded or clipped with its parent; that is why clipping and fading meant for it must come AFTER the shared modifier.')
    m('simp.1', 'Kích thước 64×64 → 360×240 và các khung trung gian là minh họa; spring mặc định (StiffnessMediumLow) cho đường đi thật khác.', 'The 64×64 → 360×240 sizes and the in-between bounds are illustrative; the default spring (StiffnessMediumLow) gives a different real path.')
    m('simp.2', 'Mô hình gộp lookahead, khớp key và bắt đầu animation vào vài bước; trong thật, isMatchFound chỉ thành true sau khi phần tử mới đã được compose (với lazy list là trong lượt đo).', 'The model folds lookahead, key matching and animation start into a few steps; in reality isMatchFound only becomes true after the new element has been composed (for a lazy list, during the measure pass).')
    m('ctl.hint', 'So "cùng key" với "khác key", rồi xem góc bo ở cách viết thứ ba.', 'Compare "same key" with "different keys", then look at the rounded corners in the third version.')
    m('ctl.which', 'Cách viết', 'Version')
    for k, vi, en in [('match', 'Cùng key "image"', 'Same key "image"'), ('nomatch', 'Khác key', 'Different keys'), ('clip', 'clip đặt trước sharedElement', 'clip placed before sharedElement')]:
        m('ctl.which.' + k, vi, en)
    m('diagramTitle', 'Màn danh sách, scope chung, overlay, màn chi tiết', 'List screen, the shared scope, the overlay, the detail screen')
    m('diagramDesc', 'Ảnh ở màn danh sách và ảnh ở màn chi tiết khớp key qua SharedTransitionScope; trong lúc bay ảnh được vẽ trong overlay', 'The list image and the detail image match keys through the SharedTransitionScope; during the flight the image is drawn in the overlay')
    for k, vi, en in [('list', 'Màn danh sách (đang rời)', 'List screen (exiting)'), ('scope', 'SharedTransitionScope', 'SharedTransitionScope'), ('overlay', 'Overlay của scope', 'The scope\'s overlay'), ('detail', 'Màn chi tiết (đang vào)', 'Detail screen (entering)')]:
        m('n.' + k, vi, en)
    for k, vi, en in [('x', 'Khung: x (px)', 'Bounds: x (px)'), ('w', 'Khung: rộng (px)', 'Bounds: width (px)'), ('active', 'Đang chuyển (isTransitionActive, 1/0)', 'Transition active (isTransitionActive, 1/0)')]:
        m('met.' + k, vi, en)
    for k, vi, en in [('match', 'isMatchFound', 'isMatchFound'), ('drawn', 'Ảnh được vẽ ở', 'Image drawn in'), ('corner', 'Góc bo khi bay', 'Corners in flight')]:
        m('st.' + k, vi, en)
    S = [
        ('intro.match', 'Màn danh sách, ảnh nhỏ có key "image"', 'List screen, the small image has key "image"', 'Ảnh có `Modifier.sharedElement(rememberSharedContentState(key = "image"), animatedVisibilityScope = this@AnimatedContent)`; màn chi tiết khai báo cùng key.', 'The image has `Modifier.sharedElement(rememberSharedContentState(key = "image"), animatedVisibilityScope = this@AnimatedContent)`; the detail screen declares the same key.'),
        ('intro.nomatch', 'Màn danh sách, key "image"; màn chi tiết dùng key "img-1"', 'List screen, key "image"; the detail screen uses key "img-1"', 'Key so bằng equals; hai chuỗi khác nhau thì không khớp.', 'Keys are compared with equals; two different strings do not match.'),
        ('intro.clip', 'Màn danh sách; ảnh có clip TRƯỚC sharedElement', 'List screen; the image has clip BEFORE sharedElement', 'Chuỗi `.clip(RoundedCornerShape(16.dp)).sharedElement(...)`: clip là modifier ngoài, nằm ở cây layout bình thường.', 'The chain `.clip(RoundedCornerShape(16.dp)).sharedElement(...)`: the clip is the outer modifier, living in the normal layout tree.'),
        ('navigate', 'Chạm: AnimatedContent chuyển sang Detail', 'Tap: AnimatedContent switches to Detail', 'Như chương C4, trong lúc chuyển cả nội dung cũ lẫn mới cùng được compose; màn chi tiết được compose lần đầu.', 'As in chapter C4, during the switch both old and new content are composed; the detail screen is composed for the first time.'),
        ('matched', 'Tìm thấy cặp khớp; lookahead cho khung đích', 'A match is found; lookahead gives the target bounds', 'Scope thấy hai phần tử cùng key: một đang rời, một đang vào. `isMatchFound` = true, `isTransitionActive` = true. Lượt lookahead đo màn chi tiết ở trạng thái cuối nên biết khung đích (0, 0, 360×240) trước khi nó thật sự ở đó.', 'The scope sees two elements with the same key: one exiting, one entering. `isMatchFound` = true, `isTransitionActive` = true. The lookahead pass measures the detail screen in its final state, so it knows the target bounds (0, 0, 360×240) before the element is really there.'),
        ('nomatchStep', 'Không khớp: chỉ có hiệu ứng của AnimatedContent', 'No match: only AnimatedContent\'s effect', 'Không có cặp cùng key nên không có animation khung: ảnh nhỏ mờ đi cùng màn danh sách, ảnh lớn hiện dần cùng màn chi tiết.', 'There is no pair with the same key, so there is no bounds animation: the small image fades out with the list screen and the large one fades in with the detail screen.'),
        ('fly', 'Bay: khung x = {x}, rộng {w}', 'Flight: bounds x = {x}, width {w}', 'Khung animate từ khung của phần tử đang rời tới khung đích (BoundsTransform mặc định là spring StiffnessMediumLow). Ảnh được vẽ trong OVERLAY của scope, nên không mờ đi cùng màn danh sách và không bị cha cắt.', 'The bounds animate from the exiting element\'s bounds to the target (the default BoundsTransform is a spring with StiffnessMediumLow). The image is drawn in the scope\'s OVERLAY, so it does not fade with the list screen and is not clipped by its parent.'),
        ('flyClip', 'Bay: khung x = {x}, rộng {w}, góc VUÔNG', 'Flight: bounds x = {x}, width {w}, SQUARE corners', 'Ảnh đang ở overlay, còn clip đặt TRƯỚC sharedElement nằm lại ở cây bình thường, nên không áp lên ảnh khi bay: góc bo biến mất trong lúc bay.', 'The image is in the overlay, while the clip placed BEFORE sharedElement stays in the normal tree, so it does not apply to the image in flight: the rounded corners disappear during the flight.'),
        ('fade', 'Màn danh sách mờ đi, màn chi tiết hiện dần', 'The list fades out, the detail fades in', 'Hiệu ứng mặc định của AnimatedContent chạy cho phần còn lại của hai màn.', 'AnimatedContent\'s default effect runs for the rest of both screens.'),
        ('done.match', 'Xong: về cây bình thường', 'Done: back in the normal tree', 'Khi mọi animation của scope xong, `isTransitionActive` = false; ảnh lớn được vẽ lại trong cây layout của màn chi tiết, màn danh sách bị gỡ.', 'When all of the scope\'s animations finish, `isTransitionActive` = false; the large image is drawn back in the detail screen\'s layout tree, and the list screen is removed.'),
        ('done.nomatch', 'Xong: hai ảnh không hề nối với nhau', 'Done: the two images were never connected', 'Cách kiểm tra nhanh: đọc `isMatchFound` của SharedContentState.', 'A quick check: read the SharedContentState\'s `isMatchFound`.'),
        ('done.clip', 'Xong: góc bo trở lại', 'Done: the corners come back', 'Về cây bình thường thì clip lại áp lên ảnh: góc "nhảy" từ vuông sang bo. Sửa: đặt `clip` SAU `sharedElement`.', 'Back in the normal tree, the clip applies again: the corners "jump" from square to rounded. Fix: put `clip` AFTER `sharedElement`.'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('key', 'KDoc: SharedTransitionScope làm việc khớp key cho mọi sharedElement/sharedBounds trong nó; khớp không hoạt động giữa hai scope khác nhau. [[src:an-shared-src]]', 'The KDoc: the SharedTransitionScope does the key matching for every sharedElement/sharedBounds inside it; matching does not work across different scopes. [[src:an-shared-src]]'),
        ('overlay', 'KDoc: khi bắt đầu chuyển, phần tử được vẽ trong overlay của scope để không bị mờ hay cắt theo cha, và ở đó tới khi isTransitionActive = false. [[src:an-shared-src]]', 'The KDoc: when the transition starts, the element is drawn in the scope\'s overlay so it is not faded or clipped with its parent, and stays there until isTransitionActive = false. [[src:an-shared-src]]'),
        ('clip', 'KDoc: mọi clip hay fade cho shared element phải áp RÕ RÀNG như con của nó, tức đặt SAU sharedElement trong chuỗi modifier. [[src:an-shared-src]]', 'The KDoc: any clipping or fading for a shared element must be applied EXPLICITLY as its child, i.e. AFTER sharedElement in the modifier chain. [[src:an-shared-src]]'),
        ('match', 'isMatchFound chỉ thành true sau khi phần tử mới cùng key đã được compose. [[src:an-shared-src]]', 'isMatchFound only becomes true after the new element with the same key has been composed. [[src:an-shared-src]]')]:
        m('co.' + k, vi, en)
    a('cap.shared', 'Màn danh sách bên trái và màn chi tiết bên phải khớp key qua SharedTransitionScope ở giữa; trong lúc bay, ảnh được vẽ trong overlay.', 'The list screen on the left and the detail screen on the right match keys through the SharedTransitionScope in the middle; during the flight, the image is drawn in the overlay.')

    C = 'se'
    a(C + '.title', 'Shared element và chuyển màn hình', 'Shared elements and screen transitions')
    a(C + '.essence',
      'Hai composable cùng `key` trong cùng một `SharedTransitionScope` (thường là `SharedTransitionLayout`) sẽ khớp; khung animate từ chỗ cũ tới khung đích mà lookahead tính trước.\n`sharedElement` cho nội dung giống hệt (ảnh, icon); `sharedBounds` cho nội dung khác nhau chung một vùng (container transform, Text).\nTrong lúc bay, phần tử vẽ trong overlay: clip và fade cho nó phải đặt SAU modifier shared; với navigation, bọc NavHost/NavDisplay trong SharedTransitionLayout.',
      'Two composables with the same `key` in the same `SharedTransitionScope` (usually `SharedTransitionLayout`) match; the bounds animate from the old place to the target that lookahead computed in advance.\n`sharedElement` is for identical content (images, icons); `sharedBounds` for different content sharing one area (container transform, Text).\nDuring the flight the element is drawn in the overlay: clipping and fading for it go AFTER the shared modifier; with navigation, wrap NavHost/NavDisplay in SharedTransitionLayout.')
    a(C + '.goal.g1', 'Đã chạm để chuyển sang màn chi tiết', 'Tapped to switch to the detail screen')
    a(C + '.goal.g2', 'Đã chạy một cách viết tới cuối', 'Ran one version to the end')
    a(C + '.sim.animation.shared', 'Shared element bên trong', 'Inside a shared element')

    S = 'hook'
    a(C + '.sec.%s.title' % S, 'Đoán trước khi đọc', 'Predict before reading')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'predict', 'Ảnh ở màn danh sách có `Modifier.clip(RoundedCornerShape(16.dp)).sharedElement(...)`. Khi bay sang màn chi tiết, ảnh còn bo góc không?', 'The list image has `Modifier.clip(RoundedCornerShape(16.dp)).sharedElement(...)`. While flying to the detail screen, are its corners still rounded?')
    B(C, S, 1, 'ans', 'Không. Trong lúc chuyển, phần tử được vẽ trong overlay của SharedTransitionScope, tách khỏi cây layout của cha; clip đặt TRƯỚC `sharedElement` nằm lại ở cây đó. KDoc yêu cầu clip và fade cho shared element phải đặt SAU modifier `sharedElement`. [[src:an-shared-src]]', 'No. During the transition the element is drawn in the SharedTransitionScope\'s overlay, apart from its parent\'s layout tree; a clip placed BEFORE `sharedElement` stays behind in that tree. The KDoc requires clipping and fading for a shared element to come AFTER the `sharedElement` modifier. [[src:an-shared-src]]')

    S = 'views'
    a(C + '.sec.%s.title' % S, 'Trước Compose: transitionName', 'Before Compose: transitionName')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', '*Android Animations by Tutorials* Ch.6 làm shared element giữa các Fragment trong hệ View qua ba bước: (1) đặt cùng `android:transitionName="logo_transition_name"` cho View ở hai màn (trong RecyclerView phải đặt tên riêng cho từng mục bằng mã, vì mọi mục cùng XML sẽ trùng tên); (2) khi chuyển Fragment, gọi `addSharedElement(sharedView, sharedView.transitionName)`; (3) đặt `sharedElementEnterTransition` cho Fragment đích, ví dụ `ChangeBounds` (animate khung layout) gộp với `ChangeTransform`. Sách lưu ý: chỉ làm (1) và (2) thì gần như không thấy gì, vì chưa nói cho framework cách animate. [[src:book-aat]]', '*Android Animations by Tutorials* Ch.6 builds a shared element between Fragments in the View system in three steps: (1) give the View on both screens the same `android:transitionName="logo_transition_name"` (in a RecyclerView each item needs its own name set in code, since items from the same XML would share it); (2) when switching Fragments, call `addSharedElement(sharedView, sharedView.transitionName)`; (3) set `sharedElementEnterTransition` on the target Fragment, for example `ChangeBounds` (animates layout bounds) combined with `ChangeTransform`. The book notes that doing only (1) and (2) shows almost nothing, because the framework has not been told how to animate. [[src:book-aat]]')
    B(C, S, 2, 'p', 'Compose giữ cùng ý tưởng nhưng đổi cách làm: `transitionName` ↔ `key` của `rememberSharedContentState`; `addSharedElement` khi chuyển màn ↔ không cần, vì scope tự khớp khi nội dung mới được compose; `ChangeBounds` ↔ `boundsTransform` (mặc định là spring); và key cũng phải duy nhất cho từng mục trong danh sách, y như transitionName. [[src:book-aat]] [[src:an-shared]]', 'Compose keeps the same idea but changes the mechanics: `transitionName` ↔ the `key` of `rememberSharedContentState`; `addSharedElement` on navigation ↔ not needed, since the scope matches automatically when the new content is composed; `ChangeBounds` ↔ `boundsTransform` (a spring by default); and keys must also be unique per list item, just like transitionName. [[src:book-aat]] [[src:an-shared]]')

    S = 'basics'
    a(C + '.sec.%s.title' % S, 'Ba API chính: SharedTransitionLayout, sharedElement, sharedBounds', 'The three main APIs: SharedTransitionLayout, sharedElement, sharedBounds')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Theo tài liệu: bọc nội dung trong `SharedTransitionLayout` (tạo một layout và cung cấp `SharedTransitionScope`); bên trong, dùng `AnimatedContent`, `AnimatedVisibility` hoặc `NavHost` để quản lý việc chuyển; trên hai composable cần nối, thêm `Modifier.sharedElement(rememberSharedContentState(key), animatedVisibilityScope)`. Composable phải nằm trong một SharedTransitionScope mới dùng được các modifier này, nên thường truyền hai scope xuống làm tham số hoặc qua CompositionLocal. [[src:an-shared]]', 'Per the docs: wrap your content in `SharedTransitionLayout` (it creates a layout and provides a `SharedTransitionScope`); inside, use `AnimatedContent`, `AnimatedVisibility` or `NavHost` to manage the switch; on the two composables to connect, add `Modifier.sharedElement(rememberSharedContentState(key), animatedVisibilityScope)`. A composable must be inside a SharedTransitionScope to use these modifiers, so you usually pass both scopes down as parameters or via a CompositionLocal. [[src:an-shared]]')
    B(C, S, 2, 'kt', 'SharedTransitionLayout {\n    AnimatedContent(showDetails, label = "screen") { details ->\n        val imageModifier = Modifier\n            .sharedElement(\n                rememberSharedContentState(key = "image"),\n                animatedVisibilityScope = this@AnimatedContent\n            )\n            .clip(RoundedCornerShape(16.dp))        // ✓ SAU sharedElement\n        if (!details) ListRow(imageModifier, onClick = { showDetails = true })\n        else DetailHeader(imageModifier, onBack = { showDetails = false })\n    }\n}', 'SharedTransitionLayout {\n    AnimatedContent(showDetails, label = "screen") { details ->\n        val imageModifier = Modifier\n            .sharedElement(\n                rememberSharedContentState(key = "image"),\n                animatedVisibilityScope = this@AnimatedContent\n            )\n            .clip(RoundedCornerShape(16.dp))        // ✓ AFTER sharedElement\n        if (!details) ListRow(imageModifier, onClick = { showDetails = true })\n        else DetailHeader(imageModifier, onBack = { showDetails = false })\n    }\n}')
    B(C, S, 3, 'p', '`sharedElement` hay `sharedBounds`? Tài liệu và KDoc: `sharedElement` cho nội dung GIỐNG HỆT nhau khi cùng constraints (ảnh, icon, MovableContent); trong lúc chuyển chỉ phần tử đang vào được vẽ; dùng cho "hero transition". `sharedBounds` cho nội dung KHÁC nhau nhưng chung một vùng; cả nội dung vào lẫn ra đều hiện (có tham số `enter`/`exit` như AnimatedVisibility); dùng cho "container transform", và nên dùng cho Text khi đổi font (nghiêng ↔ đậm) hay màu. [[src:an-shared]] [[src:an-shared-src]]', '`sharedElement` or `sharedBounds`? Docs and KDoc: `sharedElement` is for content that is IDENTICAL under the same constraints (images, icons, MovableContent); during the transition only the entering element is drawn; it is for the "hero transition". `sharedBounds` is for DIFFERENT content sharing one area; both entering and exiting content are visible (with `enter`/`exit` parameters like AnimatedVisibility); it is for the "container transform", and is preferred for Text when the font (italic ↔ bold) or colour changes. [[src:an-shared]] [[src:an-shared-src]]')
    B(C, S, 4, 'p', 'Key: tài liệu khuyên không dùng chuỗi cho trường hợp phức tạp vì dễ gõ sai, mà dùng `data class` (có sẵn `equals`/`hashCode`), ví dụ `SnackSharedElementKey(snackId, origin, type)`: cùng một món có thể xuất hiện ở mục "Popular" và "Recommended", nên `origin` phân biệt hai chỗ. Muốn biết có khớp không, lấy `rememberSharedContentState(...)` ra biến và đọc `isMatchFound`. [[src:an-shared]] [[src:an-shared-src]]', 'Keys: for complex cases the docs advise against strings, since they are easy to mistype, and recommend a `data class` (which brings `equals`/`hashCode`), for example `SnackSharedElementKey(snackId, origin, type)`: the same snack can appear in a "Popular" and a "Recommended" section, so `origin` tells the two places apart. To know whether a match happened, pull `rememberSharedContentState(...)` into a variable and read `isMatchFound`. [[src:an-shared]] [[src:an-shared-src]]')

    S = 'inside'
    a(C + '.sec.%s.title' % S, 'Bên trong: lookahead, khớp key, overlay', 'Inside: lookahead, key matching, the overlay')
    a(C + '.sec.%s.badge' % S, 'impl')
    B(C, S, 1, 'p', 'Ở commit ghim, `SharedTransitionLayout(modifier, content)` chỉ là `SharedTransitionScope { m -> Box(modifier.then(m)) { content() } }`, và composable `SharedTransitionScope` mở đầu bằng `LookaheadScope { … }`. Lookahead là một lượt đo/đặt "nhìn trước" trạng thái đích: nhờ nó, scope biết khung cuối cùng của phần tử đang vào trước khi phần tử thật sự tới đó. Đây cũng là lý do `animateContentSize` ở chương C5 lấy kích thước lookahead làm đích khi có. [[src:an-shared-src]]', 'At the pinned commit, `SharedTransitionLayout(modifier, content)` is just `SharedTransitionScope { m -> Box(modifier.then(m)) { content() } }`, and the `SharedTransitionScope` composable starts with `LookaheadScope { … }`. Lookahead is a measure/place pass that "looks ahead" at the target state: thanks to it, the scope knows the entering element\'s final bounds before the element actually gets there. This is also why `animateContentSize` in chapter C5 uses the lookahead size as its target when present. [[src:an-shared-src]]')
    B(C, S, 2, 'p', 'KDoc của `SharedTransitionScope` nêu ba trách nhiệm: (1) là không gian tọa độ, vị trí animate luôn tính từ gốc của scope; (2) tạo một OVERLAY, nơi mọi shared element/bounds được vẽ theo mặc định trong lúc chuyển, để chúng không bị mờ theo cha hay bị cha cắt; ở đó tới khi mọi animation trong scope xong (`isTransitionActive` = false); (3) khớp key cho mọi `sharedElement`/`sharedBounds` trong nó; key tạo ở hai scope khác nhau thì KHÔNG khớp. [[src:an-shared-src]]', 'The `SharedTransitionScope` KDoc lists three responsibilities: (1) it is the coordinate space; animated positions are always relative to the scope\'s origin; (2) it creates an OVERLAY, where all shared elements/bounds are drawn by default during the transition, so they are not faded with their parent or clipped by it; they stay there until all animations in the scope finish (`isTransitionActive` = false); (3) it matches keys for every `sharedElement`/`sharedBounds` inside it; keys created in two different scopes do NOT match. [[src:an-shared-src]]')
    B(C, S, 3, 'p', 'Hệ quả thực hành, theo KDoc và tài liệu: clip/fade cho shared element đặt SAU modifier shared; `zIndexInOverlay` chọn thứ tự vẽ trong overlay (ví dụ cho tiêu đề bay trên cùng); `clipInOverlayDuringTransition` cắt phần tử trong overlay (mặc định theo `sharedBounds` cha); `placeholderSize` quyết định cha thấy kích thước nào (mặc định kích thước nội dung; `AnimatedSize` làm cha và anh em đo lại mỗi frame). BoundsTransform mặc định là spring `StiffnessMediumLow`; `boundsTransform` cho phép dùng spec khác, ví dụ keyframes có `ArcMode` để bay theo đường cong. [[src:an-shared-src]] [[src:an-shared-custom]]', 'Practical consequences, per the KDoc and docs: clipping/fading for a shared element go AFTER the shared modifier; `zIndexInOverlay` picks the draw order in the overlay (say, to fly a title on top); `clipInOverlayDuringTransition` clips the element in the overlay (by default following its parent `sharedBounds`); `placeholderSize` decides what size the parent sees (the content size by default; `AnimatedSize` makes the parent and siblings re-measure every frame). The default BoundsTransform is a `StiffnessMediumLow` spring; `boundsTransform` lets you use another spec, for example keyframes with an `ArcMode` to fly along a curve. [[src:an-shared-src]] [[src:an-shared-custom]]')
    B(C, S, 4, 'note', 'Phiên bản: tài liệu và nhiều bài viết cũ đặt `@OptIn(ExperimentalSharedTransitionApi::class)`. Tại commit ghim, các API trong `SharedTransitionScope.kt` không còn mang annotation thử nghiệm đó (file annotation vẫn tồn tại). Nếu bản Compose bạn dùng còn đòi opt-in, hãy thêm vào; đừng suy ra ngày nó thành ổn định từ site này. [[src:an-shared-src]]', 'Versions: the docs and many older articles add `@OptIn(ExperimentalSharedTransitionApi::class)`. At the pinned commit, the APIs in `SharedTransitionScope.kt` no longer carry that experimental annotation (the annotation file still exists). If your Compose version still requires the opt-in, add it; do not infer from this site when it became stable. [[src:an-shared-src]]')
    B(C, S, 4, 'kind', 'source')
    B(C, S, 5, 'p', 'Mô phỏng ngay dưới chạy cả ba hệ quả: khớp key; không khớp; và clip đặt sai chỗ khi phần tử đang ở overlay.', 'The simulation just below runs all three consequences: a key match; no match; and a misplaced clip while the element is in the overlay.')

    S = 'resize'
    a(C + '.sec.%s.title' % S, 'Thứ tự modifier và resizeMode', 'Modifier order and resizeMode')
    a(C + '.sec.%s.badge' % S, 'guideline')
    B(C, S, 1, 'p', 'Tài liệu: thứ tự modifier quanh `sharedElement`/`sharedBounds` quan trọng như mọi nơi trong Compose. Modifier đứng TRƯỚC cung cấp constraints để tính khung đầu và khung đích; modifier đứng SAU đo con theo constraints đó. Đặt modifier kích thước (như `padding`) ở vị trí khác nhau trên hai phần tử khớp sẽ gây "giật" khi khớp. Nên đặt modifier kích thước SAU modifier shared, trừ `requiredSize()`. [[src:an-shared]]', 'The docs: modifier order around `sharedElement`/`sharedBounds` matters as everywhere in Compose. Modifiers BEFORE provide the constraints used to derive the initial and target bounds; modifiers AFTER measure the child within those constraints. Putting a size-affecting modifier (such as `padding`) in different positions on the two matching elements causes a visual jump at match time. Place size modifiers AFTER the shared modifier, except `requiredSize()`. [[src:an-shared]]')
    B(C, S, 2, 'p', '`sharedBounds` có `resizeMode`: `scaleToBounds()` (mặc định) đo con MỘT lần bằng constraints lookahead rồi PHÓNG TO/THU NHỎ bố cục ổn định đó cho vừa khung, như một phép scale đồ họa, nên Text không xuống dòng lại; `RemeasureToBounds` đo lại con mỗi frame với constraints cố định từ khung đang animate, hợp với khung khác tỉ lệ hoặc khi muốn bố cục chảy liên tục. Còn `sharedElement` luôn đo lại con theo kích thước đang animate (giống RemeasureToBounds). [[src:an-shared-custom]] [[src:an-shared-src]]', '`sharedBounds` has a `resizeMode`: `scaleToBounds()` (the default) measures the child ONCE with the lookahead constraints and then SCALES that stable layout to fit the bounds, like a graphical scale, so Text does not re-wrap; `RemeasureToBounds` re-measures the child every frame with fixed constraints from the animating bounds, suited to bounds of different aspect ratios or when you want the layout to flow continuously. `sharedElement` always re-measures its child to the animating size (like RemeasureToBounds). [[src:an-shared-custom]] [[src:an-shared-src]]')

    S = 'nav'
    a(C + '.sec.%s.title' % S, 'Với navigation và predictive back', 'With navigation and predictive back')
    a(C + '.sec.%s.badge' % S, 'version')
    B(C, S, 1, 'p', 'Tài liệu navigation: với Navigation 3, bọc `NavDisplay` trong `SharedTransitionLayout` và lấy `AnimatedContentScope` qua `LocalNavAnimatedContentScope`; với Navigation 2, bọc `NavHost` trong `SharedTransitionLayout`, và lambda `composable { }` có receiver là `AnimatedContentScope` nên dùng `this@composable`. Predictive back chạy được với shared element: mọi bản Navigation 3, và Navigation 2 từ bản tài liệu nêu. Trên Android 15 (API 35) trở lên predictive back bật mặc định; Android 14 cần bật trong developer options; app nhắm Android 14 trở xuống phải thêm `android:enableOnBackInvokedCallback="true"`. [[src:an-shared-nav]]', 'The navigation docs: with Navigation 3, wrap `NavDisplay` in `SharedTransitionLayout` and get the `AnimatedContentScope` through `LocalNavAnimatedContentScope`; with Navigation 2, wrap `NavHost` in `SharedTransitionLayout`, and the `composable { }` lambda has `AnimatedContentScope` as its receiver, so use `this@composable`. Predictive back works with shared elements: all Navigation 3 versions, and Navigation 2 from the version the docs name. On Android 15 (API 35) and up predictive back is on by default; Android 14 needs it enabled in developer options; apps targeting Android 14 or lower must add `android:enableOnBackInvokedCallback="true"`. [[src:an-shared-nav]]')
    B(C, S, 2, 'note', 'Giới hạn tài liệu nêu: không hỗ trợ trộn View và Compose (kể cả composable bọc `AndroidView`, như `Dialog`); không tự animate giữa hai hình dạng clip khác nhau. Với các trường hợp đó, dùng `sharedBounds` và thêm `Modifier.animateEnterExit()` cho các mục. [[src:an-shared]]', 'Limits the docs list: no interop between Views and Compose (including composables wrapping `AndroidView`, such as `Dialog`); no automatic animation between two different clip shapes. For those cases, use `sharedBounds` and add `Modifier.animateEnterExit()` to the items. [[src:an-shared]]')
    B(C, S, 2, 'kind', 'pitfall')

    S = 'bugs'
    a(C + '.sec.%s.title' % S, 'Bug thường gặp', 'Common bugs')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'bug', 'Ảnh không bay mà chỉ mờ đi rồi hiện lại.', 'The image does not fly; it just fades out and back in.')
    B(C, S, 1, 'cause', 'Không có cặp khớp: key khác nhau (gõ sai chuỗi, hoặc id khác kiểu), hoặc hai phần tử nằm trong hai SharedTransitionScope khác nhau.', 'There is no matching pair: different keys (a mistyped string, or an id of a different type), or the two elements are in two different SharedTransitionScopes.')
    B(C, S, 1, 'fix', 'Dùng data class làm key, một SharedTransitionLayout bao cả hai màn, và đọc `isMatchFound` để kiểm. [[src:an-shared]] [[src:an-shared-src]]', 'Use a data class key, one SharedTransitionLayout around both screens, and read `isMatchFound` to check. [[src:an-shared]] [[src:an-shared-src]]')
    B(C, S, 2, 'bug', 'Góc bo của ảnh biến mất trong lúc bay rồi "nhảy" lại khi xong.', 'The image\'s rounded corners vanish during the flight and "jump" back when done.')
    B(C, S, 2, 'cause', '`clip` đặt TRƯỚC `sharedElement`; ảnh bay trong overlay nên clip của cây bình thường không áp lên.', '`clip` is placed BEFORE `sharedElement`; the image flies in the overlay, so the normal tree\'s clip does not apply.')
    B(C, S, 2, 'fix', 'Đặt `clip` SAU `sharedElement`, hoặc dùng `clipInOverlayDuringTransition`. [[src:an-shared-src]]', 'Put `clip` AFTER `sharedElement`, or use `clipInOverlayDuringTransition`. [[src:an-shared-src]]')
    B(C, S, 3, 'bug', 'Trong danh sách, bấm một mục thì một mục KHÁC bay sang màn chi tiết.', 'In a list, tapping one item makes a DIFFERENT item fly to the detail screen.')
    B(C, S, 3, 'cause', 'Mọi mục dùng cùng một key (ví dụ "image"), giống lỗi trùng transitionName trong RecyclerView mà sách AAT nhắc.', 'Every item uses the same key (say, "image"), like the duplicate transitionName problem in a RecyclerView that the AAT book mentions.')
    B(C, S, 3, 'fix', 'Đưa id của mục vào key: `SnackSharedElementKey(snack.id, origin, type)`. [[src:an-shared]] [[src:book-aat]]', 'Put the item id into the key: `SnackSharedElementKey(snack.id, origin, type)`. [[src:an-shared]] [[src:book-aat]]')

    S = 'exercises'
    a(C + '.sec.%s.title' % S, 'Bài tập', 'Exercises')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ex', 'Danh sách thẻ món ăn → màn chi tiết: ảnh bay (hero), còn khung thẻ nở thành nền của màn chi tiết (container transform); tiêu đề đổi từ chữ thường sang chữ đậm.', 'A list of food cards → a detail screen: the image flies (hero), the card frame grows into the detail background (container transform); the title changes from regular to bold.')
    B(C, S, 1, 'hint', 'Ảnh: sharedElement. Khung thẻ: sharedBounds với resizeMode mặc định. Tiêu đề: sharedBounds (tài liệu khuyên cho Text đổi font).', 'Image: sharedElement. Card frame: sharedBounds with the default resizeMode. Title: sharedBounds (the docs recommend it for Text with font changes).')
    B(C, S, 1, 'sol', 'Key cho từng phần: `FoodKey(food.id, Part.Image)`, `FoodKey(food.id, Part.Card)`, `FoodKey(food.id, Part.Title)`; cả ba nằm trong cùng một SharedTransitionLayout bao AnimatedContent; `clip` của thẻ đặt sau `sharedBounds`, hoặc dùng `clipInOverlayDuringTransition` để ảnh không bay ra ngoài thẻ.', 'Keys per part: `FoodKey(food.id, Part.Image)`, `FoodKey(food.id, Part.Card)`, `FoodKey(food.id, Part.Title)`; all three in the same SharedTransitionLayout around AnimatedContent; the card\'s `clip` goes after `sharedBounds`, or use `clipInOverlayDuringTransition` so the image does not fly outside the card.')

    S = 'recall'
    a(C + '.sec.%s.title' % S, 'Tự trả lời', 'Answer it yourself')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ask', 'Vì sao scope biết khung đích của phần tử đang vào trước khi nó tới đó?', 'How does the scope know the entering element\'s target bounds before it gets there?')
    B(C, S, 1, 'ans', 'SharedTransitionScope là một LookaheadScope: lượt lookahead đo và đặt trạng thái đích trước.', 'SharedTransitionScope is a LookaheadScope: the lookahead pass measures and places the target state first.')
    B(C, S, 2, 'ask', 'Trong lúc chuyển, shared element được vẽ ở đâu, và hệ quả với clip?', 'During the transition, where is a shared element drawn, and what does that mean for clipping?')
    B(C, S, 2, 'ans', 'Trong overlay của scope; clip/fade muốn áp lên nó phải đặt sau modifier shared.', 'In the scope\'s overlay; clipping/fading meant for it must come after the shared modifier.')
    for q, qv, qe, av, ae, wv, we in [
        ('q1', 'Text đổi từ nghiêng sang đậm giữa hai màn nên dùng gì?', 'Text changing from italic to bold between two screens should use what?', 'sharedBounds.', 'sharedBounds.', 'Tài liệu khuyên sharedBounds cho Text khi đổi font hoặc màu.', 'The docs recommend sharedBounds for Text when font or colour changes.'),
        ('q2', 'Hai phần tử cùng key nhưng ở hai SharedTransitionLayout khác nhau có khớp không?', 'Do two elements with the same key in two different SharedTransitionLayouts match?', 'Không.', 'No.', 'KDoc: khớp key không hoạt động giữa các scope khác nhau.', 'The KDoc: key matching does not work across different scopes.'),
        ('q3', 'resizeMode mặc định của sharedBounds là gì?', 'What is sharedBounds\' default resizeMode?', 'scaleToBounds().', 'scaleToBounds().', 'Đo một lần bằng constraints lookahead rồi scale cho vừa khung.', 'It measures once with the lookahead constraints and then scales to fit the bounds.'),
        ('q4', 'Shared element có hoạt động với composable bọc AndroidView (như Dialog)?', 'Do shared elements work with composables wrapping AndroidView (such as Dialog)?', 'Không.', 'No.', 'Tài liệu nêu đây là một giới hạn: không có tương tác View–Compose.', 'The docs list this as a limitation: no View–Compose interop.')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)
